"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$existing = Get-NetTCPConnection -LocalPort 3000 -State Listen -ErrorAction SilentlyContinue
if ($existing) { throw "Port 3000 is already in use before npm start validation" }
$stdoutPath = Join-Path $env:TEMP '"'tasker-signal-npm-start.stdout.log'
"'$stderrPath = Join-Path $env:TEMP '"'tasker-signal-npm-start.stderr.log'
Remove-Item -LiteralPath "'$stdoutPath, $stderrPath -Force -ErrorAction SilentlyContinue
$server = Start-Process -FilePath '"'npm.cmd' -ArgumentList @('start') -WorkingDirectory (Get-Location).Path -WindowStyle Hidden -PassThru -RedirectStandardOutput "'$stdoutPath -RedirectStandardError $stderrPath
try {
  $response = $null
  for ($attempt = 0; $attempt -lt 30; $attempt++) {
    Start-Sleep -Milliseconds 500
    try {
      $response = Invoke-WebRequest -Uri '"'http://127.0.0.1:3000' -UseBasicParsing -TimeoutSec 2
      break
    } catch {
      if ("'$server.HasExited) { break }
    }
  }
  Get-Content -LiteralPath $stdoutPath -ErrorAction SilentlyContinue
  Get-Content -LiteralPath $stderrPath -ErrorAction SilentlyContinue
  if (-not $response) { throw '"'npm start did not become reachable on port 3000' }
  \"HTTP_STATUS="'$($response.StatusCode)"
} finally {
  $all = Get-CimInstance Win32_Process
  $ids = [System.Collections.Generic.HashSet[int]]::new()
  [void]$ids.Add($server.Id)
  do {
    $added = $false
    foreach ($process in $all) {
      if ($ids.Contains([int]$process.ParentProcessId) -and $ids.Add([int]$process.ProcessId)) { $added = $true }
    }
  } while ($added)
  foreach ($id in @($ids) | Sort-Object -Descending) {
    Stop-Process -Id $id -Force -ErrorAction SilentlyContinue
  }
  Remove-Item -LiteralPath $stdoutPath, $stderrPath -Force -ErrorAction SilentlyContinue
}'

